// Point-in-polygon using ray casting
'use strict';

function pnpoly(xs, ys, n, testx, testy) {
    let inside = false;
    let j = n - 1;
    for (let i = 0; i < n; i++) {
        const yi = ys[i], yj = ys[j];
        if ((yi > testy) !== (yj > testy)) {
            const xtest = (xs[j] - xs[i]) * (testy - yi) / (yj - yi) + xs[i];
            if (testx < xtest) {
