// BENG Benchmark: binary-trees (Node.js reference)
// Allocate and deallocate binary trees to stress GC

const N = 10;

function make(depth) {
    if (depth === 0) return { left: null, right: null };
    return { left: make(depth - 1), right: make(depth - 1) };
}

function check(node) {
    if (node.left === null) return 1;
    return 1 + check(node.left) + check(node.right);
}


function main() {
let __bench_report = "";


const maxDepth = Math.max(6, N);
const stretchDepth = maxDepth + 1;
__bench_report += "stretch tree of depth " + stretchDepth + "\t check: " + check(make(stretchDepth)) + "\n";

const longLivedTree = make(maxDepth);

for (let depth = 4; depth <= maxDepth; depth += 2) {
    const iterations = 1 << (maxDepth - depth + 4);
    let sum = 0;
    for (let i = 0; i < iterations; i++) {
        sum += check(make(depth));
    }
    __bench_report += iterations + "\t trees of depth " + depth + "\t check: " + sum + "\n";
}

__bench_report += "long lived tree of depth " + maxDepth + "\t check: " + check(longLivedTree) + "\n";


return __bench_report;
}
